                String attributeValue4 = xmlPullParserNewPullParser.getAttributeValue("", Scene.CAMERA_TWEEN_OWNER_TYPE);
                if (!TextUtils.isEmpty(attributeValue4)) {
                    frame.mCameraMove.deserialize(attributeValue4);
                }
                String attributeValue5 = xmlPullParserNewPullParser.getAttributeValue("", "bg_name");
                if (!TextUtils.isEmpty(attributeValue5)) {
                    frame.setBg(attributeValue5);
