                }
                String attributeValue11 = xmlPullParserNewPullParser.getAttributeValue("", "pivot_points");
                if (!TextUtils.isEmpty(attributeValue11)) {
                    hostScene.mSpeedModifier.setPoints((SpeedPoint[]) StickmanApp.sGson.fromJson(attributeValue11, SpeedPoint[].class));
                }
                String attributeValue12 = xmlPullParserNewPullParser.getAttributeValue("", "masks");
                if (!TextUtils.isEmpty(attributeValue12)) {
                    hostScene.mMasks.readFromJson(attributeValue12);
